import * as T from './vendor/three.module.js';
export function wheelThumbnails({items,makeModel,rig,environment,disposeModel}){
 const renderer=new T.WebGLRenderer({alpha:true,antialias:true,preserveDrawingBuffer:true});renderer.setSize(144,144);renderer.setPixelRatio(1);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;
 const scene=new T.Scene();scene.environment=environment;scene.add(new T.HemisphereLight(0xffffff,0x444444,2));const light=new T.DirectionalLight(0xffffff,3);light.position.set(3,4,5);scene.add(light);const camera=new T.PerspectiveCamera(30,1,.001,100);const images={};
 try{for(const item of items){const model=makeModel(item);try{model.updateMatrixWorld(true);const source=model.getObjectByName(rig.wheels[0].name);if(!source)throw Error('Wheel thumbnail mesh missing');const wheel=source.clone(true);wheel.matrix.copy(source.matrixWorld);wheel.matrix.decompose(wheel.position,wheel.quaternion,wheel.scale);const group=new T.Group();group.add(wheel);scene.add(group);const box=new T.Box3().setFromObject(group),center=box.getCenter(new T.Vector3()),size=box.getSize(new T.Vector3());group.position.sub(center);const radius=Math.max(size.y,size.z)*.5;camera.position.set((Math.sign(rig.wheels[0].position[0])||1)*radius*4.9,radius*.10,radius*.06);camera.lookAt(0,0,0);renderer.render(scene,camera);images[item.id]=renderer.domElement.toDataURL('image/png');scene.remove(group);}finally{disposeModel(model);}}}finally{renderer.dispose();renderer.forceContextLoss();}return images;
}
